/**
 * Shared types for the D1 schema in `migrations/`.
 *
 * Conventions:
 * - Timestamps are UNIX milliseconds in UTC. Nothing here reads the clock;
 *   callers pass the current time in.
 * - Entity IDs are UUID strings generated by the caller (`newId()` in
 *   `src/db`). Audit log entries use an autoincrement integer.
 */

/** UNIX time in milliseconds, UTC. */
export type UnixMillis = number;

export const AGENT_STATUSES = ["active", "suspended"] as const;
export type AgentStatus = (typeof AGENT_STATUSES)[number];

/**
 * What a token grants access to.
 * - `participant`: the MCP connection used to ask and answer.
 * - `admin`: the administrator bot connection (design 5.3).
 * - `unread_count`: the unread count endpoint only (design 2.5).
 */
export const TOKEN_PURPOSES = ["participant", "admin", "unread_count"] as const;
export type TokenPurpose = (typeof TOKEN_PURPOSES)[number];

export const MESSAGE_KINDS = ["question", "answer", "rejection"] as const;
export type MessageKind = (typeof MESSAGE_KINDS)[number];

/**
 * Lifecycle of a message.
 * - `pending`: question waiting for an answer; deliverable to the recipient.
 * - `answered`: question the recipient answered.
 * - `declined`: question the recipient declined.
 * - `expired`: question nobody answered before `expiresAt`.
 * - `blocked`: question the bridge rejected; never delivered, but still
 *   counted toward the sender's daily limit.
 * - `sent`: the only status of answers and rejections; deliverable to the
 *   asker.
 */
export const MESSAGE_STATUSES = [
	"pending",
	"answered",
	"declined",
	"expired",
	"blocked",
	"sent",
] as const;
export type MessageStatus = (typeof MESSAGE_STATUSES)[number];

/** Statuses a question can have. */
export const QUESTION_STATUSES = [
	"pending",
	"answered",
	"declined",
	"expired",
	"blocked",
] as const satisfies readonly MessageStatus[];
export type QuestionStatus = (typeof QUESTION_STATUSES)[number];

/**
 * Statuses of messages that an inbox fetch may hand over, provided
 * `receivedAt` is still null.
 */
export const DELIVERABLE_STATUSES = [
	"pending",
	"sent",
] as const satisfies readonly MessageStatus[];

export const AUDIT_EVENT_TYPES = [
	"question_accepted",
	"question_blocked",
	"question_delivered",
	"question_answered",
	"question_declined",
	"question_expired",
	"auth_failed",
	"admin_tool_called",
	"admin_tool_denied",
	"admin_body_read",
	"description_submitted",
	"webhook_delivered",
	"webhook_abandoned",
] as const;
export type AuditEventType = (typeof AUDIT_EVENT_TYPES)[number];

export const AUDIT_OUTCOMES = ["ok", "denied", "expired"] as const;
export type AuditOutcome = (typeof AUDIT_OUTCOMES)[number];

/**
 * Internal reasons for a denial. They go to the audit log only and must
 * never be returned to the asking agent (design 3.4).
 */
export const REASON_CODES = [
	"recipient_not_found",
	"sender_suspended",
	"recipient_suspended",
	"self_addressed",
	"category_not_found",
	"no_allow_rule",
	"daily_limit_exceeded",
	"token_missing",
	"token_unknown",
	"token_revoked",
	"not_admin_bot",
	"permission_denied",
	"webhook_delivery_failed",
] as const;
export type ReasonCode = (typeof REASON_CODES)[number];

export interface Agent {
	id: string;
	ownerId: string;
	name: string;
	description: string;
	status: AgentStatus;
	dailyQuestionLimit: number;
	createdAt: UnixMillis;
}

export interface Token {
	id: string;
	agentId: string;
	/** Hash of the token. The plaintext is never stored. */
	tokenHash: string;
	purpose: TokenPurpose;
	createdAt: UnixMillis;
	/** Null while the token is valid. */
	revokedAt: UnixMillis | null;
}

export interface Category {
	id: string;
	name: string;
}

export interface AllowRule {
	fromAgentId: string;
	toAgentId: string;
	categoryId: string;
	createdAt: UnixMillis;
}

export interface Message {
	id: string;
	kind: MessageKind;
	/** Null only on a rejection of a question whose recipient did not exist. */
	fromAgentId: string | null;
	/** Null only on a blocked question whose recipient did not exist. */
	toAgentId: string | null;
	/** Null only when a blocked question named a category that did not exist. */
	categoryId: string | null;
	/** Null on rejections, and after the body has been deleted. */
	body: string | null;
	/** The question this answer or rejection replies to; null on questions. */
	inReplyTo: string | null;
	status: MessageStatus;
	createdAt: UnixMillis;
	/** When the recipient fetched the message from its inbox. */
	receivedAt: UnixMillis | null;
	/** Set on questions; null on answers and rejections. */
	expiresAt: UnixMillis | null;
	bodyDeletedAt: UnixMillis | null;
}

export interface AuditLogEntry {
	id: number;
	occurredAt: UnixMillis;
	eventType: AuditEventType;
	fromAgentId: string | null;
	toAgentId: string | null;
	categoryId: string | null;
	outcome: AuditOutcome;
	reasonCode: ReasonCode | null;
	messageId: string | null;
	/** Null unless body recording is enabled. */
	body: string | null;
}

/** An audit log entry before the database assigns its ID. */
export type NewAuditLogEntry = Omit<AuditLogEntry, "id">;

export const CHANGE_ACTOR_TYPES = ["owner", "admin_bot"] as const;
export type ChangeActorType = (typeof CHANGE_ACTOR_TYPES)[number];

export const CHANGE_TARGET_TYPES = [
	"agent",
	"token",
	"category",
	"allow_rule",
	"admin_bot",
	"description",
] as const;
export type ChangeTargetType = (typeof CHANGE_TARGET_TYPES)[number];

export const CHANGE_ACTIONS = [
	"agent_registered",
	"agent_updated",
	"agent_deleted",
	"agent_suspended",
	"agent_resumed",
	"token_issued",
	"token_revoked",
	"category_created",
	"category_deleted",
	"allow_rule_granted",
	"allow_rule_revoked",
	"admin_bot_designated",
	"admin_bot_cleared",
	"admin_bot_switches_updated",
	"description_approved",
	"description_rejected",
	"webhook_configured",
	"webhook_secret_rotated",
	"webhook_deleted",
	"change_reverted",
] as const;
export type ChangeAction = (typeof CHANGE_ACTIONS)[number];

export interface AdminBotConfig {
	agentId: string | null;
	readBodies: boolean;
	superadminUntil: UnixMillis | null;
	updatedAt: UnixMillis;
}

export interface ChangeLogEntry {
	id: number;
	occurredAt: UnixMillis;
	actorType: ChangeActorType;
	actorId: string;
	approverId: string | null;
	action: ChangeAction;
	targetType: ChangeTargetType;
	targetId: string;
	beforeJson: string | null;
	afterJson: string | null;
	revertedAt: UnixMillis | null;
}

/** A change log entry before the database assigns its ID. */
export type NewChangeLogEntry = Omit<ChangeLogEntry, "id">;

export const PROPOSAL_KINDS = [
	"grant_allow_rule",
	"create_category",
	"raise_daily_limit",
	"resume_agent",
] as const;
export type ProposalKind = (typeof PROPOSAL_KINDS)[number];

export const PROPOSAL_STATUSES = [
	"pending",
	"approved",
	"rejected",
	"expired",
] as const;
export type ProposalStatus = (typeof PROPOSAL_STATUSES)[number];

export type ProposalPayload =
	| {
			kind: "grant_allow_rule";
			fromAgentId: string;
			toAgentId: string;
			categoryId: string;
	  }
	| {
			kind: "create_category";
			name: string;
	  }
	| {
			kind: "raise_daily_limit";
			agentId: string;
			newLimit: number;
	  }
	| {
			kind: "resume_agent";
			agentId: string;
	  };

export interface Proposal {
	id: string;
	kind: ProposalKind;
	proposerAgentId: string;
	payload: ProposalPayload;
	reason: string;
	status: ProposalStatus;
	createdAt: UnixMillis;
	expiresAt: UnixMillis;
	resolvedAt: UnixMillis | null;
	resolvedBy: string | null;
	changeLogId: number | null;
}

export interface PendingDescription {
	agentId: string;
	submissionId: string;
	description: string;
	submittedAt: UnixMillis;
}

export const WEBHOOK_AUTH_MODES = [
	"standard_webhooks",
	"bearer_header",
	"custom_header",
	"paab_hmac",
] as const;
export type WebhookAuthMode = (typeof WEBHOOK_AUTH_MODES)[number];

export const WEBHOOK_DELIVERY_STATUSES = [
	"pending",
	"delivered",
	"abandoned",
] as const;
export type WebhookDeliveryStatus = (typeof WEBHOOK_DELIVERY_STATUSES)[number];

export type WebhookAuthConfig =
	| { authMode: "standard_webhooks"; secret: string }
	| { authMode: "bearer_header"; secret: string }
	| { authMode: "custom_header"; headerName: string; secret: string }
	| { authMode: "paab_hmac"; secret: string };

export type AgentWebhook = WebhookAuthConfig & {
	agentId: string;
	url: string;
	createdAt: UnixMillis;
	updatedAt: UnixMillis;
};

export interface WebhookDelivery {
	id: string;
	agentId: string;
	status: WebhookDeliveryStatus;
	attempts: number;
	nextAttemptAt: UnixMillis;
	leasedUntil: UnixMillis | null;
	lastError: string | null;
	createdAt: UnixMillis;
	updatedAt: UnixMillis;
}
